const inputData = $input.item.json;
let rawText = '';

// 1. Ambil teks dari struktur node
if (inputData.content && inputData.content.parts && inputData.content.parts[0]) {
    rawText = inputData.content.parts[0].text;
} else if (inputData.text) {
    rawText = inputData.text;
} else {
    rawText = JSON.stringify(inputData);
}

let aiData = {
    sentiment: 'Neutral',
    emotion: 'Neutral',
    support_score: 50,
    key_topics: [],
    opinion_type: 'General'
};

try {
    // 2. Parse JSON utuh
    const jsonMatch = rawText.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
        aiData = (new Function('return ' + jsonMatch[0]))();
    } else {
        throw new Error("Tidak ada kurung kurawal");
    }
} catch (e) {
    // 3. ULTIMATE FALLBACK: Ekstrak paksa pakai Regex tanpa summary
    const sentMatch = rawText.match(/"sentiment"\s*:\s*"([^"]+)"/i);
    if (sentMatch) aiData.sentiment = sentMatch[1];

    const emoMatch = rawText.match(/"emotion"\s*:\s*"([^"]+)"/i);
    if (emoMatch) aiData.emotion = emoMatch[1];

    const scoreMatch = rawText.match(/"support_score"\s*:\s*(\d+)/i);
    if (scoreMatch) aiData.support_score = parseInt(scoreMatch[1]);

    const typeMatch = rawText.match(/"opinion_type"\s*:\s*"([^"]+)"/i);
    if (typeMatch) aiData.opinion_type = typeMatch[1];
}

// 4. Ambil data asli tweet
let originalTweet = {};
try {
    originalTweet = $('Loop Tweets').item.json;
} catch (err) {
    originalTweet = $input.item.json; 
}

// 5. Gabungkan dan kirim ke MongoDB (bersih tanpa summary)
return {
    json: {
        tweet_id: originalTweet.tweet_id || Math.random().toString(),
        text_analyzed: originalTweet.text || originalTweet.text_analyzed || '',
        author: originalTweet.author_username || originalTweet.author || 'unknown',
        tweet_url: originalTweet.tweet_url || '',
        tweet_created_at: originalTweet.created_at || originalTweet.tweet_created_at || new Date().toISOString(),

        sentiment: aiData.sentiment || 'Neutral',
        emotion: aiData.emotion || 'Neutral',
        support_score: parseInt(aiData.support_score) || 50,
        key_topics: Array.isArray(aiData.key_topics) ? aiData.key_topics : [],
        opinion_type: aiData.opinion_type || 'General',
        analyzed_at: new Date().toISOString()
    }
};
